/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `updateValue` BEFORE UPDATE ON `bctc_new` FOR EACH ROW BEGIN
    -- Tính NPL
    IF NEW.TongChoVay <> 0 THEN
        SET NEW.NPL = (NEW.NoCoKhaNangMatVon + NEW.NoNghiNgo + NEW.NoDuoiTieuChuan) / NEW.TongChoVay * 100;
    ELSE
        SET NEW.NPL = 0;
    END IF;

    -- Tính LDR
    IF NEW.TongTienGui <> 0 THEN
        SET NEW.LDR = NEW.TongChoVay / NEW.TongTienGui * 100;
    ELSE
        SET NEW.LDR = 0;
    END IF;

    -- Tính LLR
    IF (NEW.NoCoKhaNangMatVon + NEW.NoNghiNgo + NEW.NoDuoiTieuChuan) <> 0 THEN
        SET NEW.LLR = NEW.TrichLuyDuPhong / (NEW.NoCoKhaNangMatVon + NEW.NoNghiNgo + NEW.NoDuoiTieuChuan) * 100;
    ELSE
        SET NEW.LLR = 0;
    END IF;

    -- Tính Tăng trưởng doanh thu
    IF NEW.DoanhThuNamNgoai <> 0 THEN
        SET NEW.TangTruongDoanhThu = (NEW.DoanhThuNamNay - NEW.DoanhThuNamNgoai) / NEW.DoanhThuNamNgoai * 100;
    ELSE
        SET NEW.TangTruongDoanhThu = 0;
    END IF;
END */;;
DELIMITER ;
